  align-items: center;
  gap: 32px;
}

.logo {
  font-size: 1.375rem;
  font-weight: 900;
  color: var(--dark);
  letter-spacing: -0.03em;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-mark {
  width: 32px;
  height: 32px;
  background: var(--primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-mark svg { width: 18px; height: 18px; fill: var(--white); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-links a {
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: var(--transition);
}

.nav-links a:hover { background: var(--gray-100); color: var(--dark); }
.nav-links a.active { color: var(--dark); font-weight: 600; }

.header-search {
  flex: 1;
