/* ============================================
   COURSES GRID
   ============================================ */

.courses-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}

.courses-grid-tight {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

/* ============================================
   HORIZONTAL SCROLL CAROUSEL
   ============================================ */

.carousel-wrapper {
  position: relative;
}

.carousel-track-outer {
  overflow: hidden;
  border-radius: var(--radius-md);
