  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.hero-arrow:hover { background: rgba(255,255,255,0.2); }
.hero-arrow svg { width: 18px; height: 18px; }

/* ============================================
   VALUE PROPOSITIONS
   ============================================ */

