  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  background: var(--gray-100);
}

.value-prop-body h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 6px;
}

.value-prop-body p {
  font-size: 0.875rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ============================================
   RESPONSIVE BREAKPOINTS
   ============================================ */

@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .carousel-track .course-card { flex: 0 0 calc(33.333% - 14px); }
  .hero-slide { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .hero-content { padding: 48px 0; }
  .hero-nav { right: 0; }
}

@media (max-width: 768px) {
  :root { --header-height: 56px; }

  .nav-links { display: none; }
  .header-search { display: none; }

  .section { padding: 48px 0; }
  .section-title { font-size: 1.5rem; }

  .courses-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }

  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col h4 { display: none; }
  .footer-accordion-header { display: flex; }
  .footer-accordion-body { display: none; padding-bottom: 16px; }
  .footer-accordion-body.open { display: block; }

  .carousel-track .course-card { flex: 0 0 calc(50% - 10px); min-width: 200px; }

  .hero-carousel { min-height: 360px; }
  .hero-slide { min-height: 360px; }
  .hero-title { font-size: 1.5rem; }

  .value-props-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .courses-grid { grid-template-columns: 1fr; }
  .promo-banner { font-size: 0.8125rem; padding: 8px 40px 8px 12px; }
}

/* ============================================
   UTILITY CLASSES
   ============================================ */

.text-primary { color: var(--primary); }
.text-teal { color: var(--teal); }
.text-muted { color: var(--gray-500); }
.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.font-bold { font-weight: 700; }
.font-extrabold { font-weight: 800; }

.flex { display: flex; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.items-center { align-items: center; }
.gap-2 { gap: 8px; }
.gap-3 { gap: 12px; }
.gap-4 { gap: 16px; }

.bg-gray { background: var(--gray-50); }
.bg-dark { background: var(--dark); }
.bg-primary { background: var(--primary); }

.w-full { width: 100%; }
.mt-4 { margin-top: 16px; }
.mt-6 { margin-top: 24px; }
.mb-4 { margin-bottom: 16px; }
.mb-6 { margin-bottom: 24px; }

.divider {
  border: none;
  border-top: 1px solid var(--gray-200);
  margin: 24px 0;
}

/* Placeholder art patterns */
.thumb-art {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
}

.thumb-art-1 { background: linear-gradient(135deg, #FF6B6B 0%, #FFE66D 100%); }
.thumb-art-2 { background: linear-gradient(135deg, #4ECDC4 0%, #2C3E50 100%); }
.thumb-art-3 { background: linear-gradient(135deg, #2193B0 0%, #6DD5ED 100%); }
.thumb-art-4 { background: linear-gradient(135deg, #f953c6 0%, #b91d73 100%); }
.thumb-art-5 { background: linear-gradient(135deg, #0F2027 0%, #2C5364 100%); }
.thumb-art-6 { background: linear-gradient(135deg, #f12711 0%, #f5af19 100%); }
.thumb-art-7 { background: linear-gradient(135deg, #834d9b 0%, #d04ed6 100%); }
.thumb-art-8 { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%); }
.thumb-art-9 { background: linear-gradient(135deg, #2d6a4f 0%, #40916c 50%, #74c69d 100%); }
.thumb-art-10 { background: linear-gradient(135deg, #e63946 0%, #457b9d 100%); }

.thumb-art::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 70% 30%, rgba(255,255,255,0.15) 0%, transparent 60%);
}

.thumb-icon {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
