    { el: 7, likes: 19, views: 847, field: 'photography' },
    { el: 8, likes: 91, views: 7234, field: 'graphic-design' },
  ];

  let timeFilter = 'all-time';

  function setTimeFilter(btn, time) {
    document.querySelectorAll('#timeFilters .filter-chip').forEach(c => c.classList.remove('active'));
    btn.classList.add('active');
    timeFilter = time;
    applyFilters();
  }

  function applyFilters() {
    const sort = document.getElementById('sortSelect').value;
    const field = document.getElementById('fieldSelect').value;
    const items = Array.from(document.querySelectorAll('#projectsGallery .masonry-item'));

    // Filter by field
    items.forEach(item => {
      const itemField = item.getAttribute('data-field') || '';
      item.style.display = (!field || itemField === field) ? '' : 'none';
    });

    // Sort
    const gallery = document.getElementById('projectsGallery');
    const sortedItems = [...items].sort((a, b) => {
      if (sort === 'most-liked') return parseInt(b.dataset.likes || 0) - parseInt(a.dataset.likes || 0);
      if (sort === 'most-viewed') return parseInt(b.dataset.views || 0) - parseInt(a.dataset.views || 0);
      if (sort === 'most-recent') return Math.random() - 0.5;
      return 0; // featured / default
    });

    sortedItems.forEach(item => gallery.appendChild(item));

    // Update count
    const visible = items.filter(i => i.style.display !== 'none').length;
    const fieldLabel = field ? `<strong style="color:var(--dark);">${document.getElementById('fieldSelect').options[document.getElementById('fieldSelect').selectedIndex].text}</strong>` : '<strong style="color:var(--dark);">all</strong>';
    document.getElementById('resultsCount').innerHTML = `Showing ${fieldLabel} projects (${visible} found)`;
  }
</script>

