  // ===== PRICING TOGGLE =====
  function togglePlan(checkbox) {
    const isMonthly = checkbox.checked;
    const card = document.getElementById('pricingCard');
    document.getElementById('priceAmount').textContent = isMonthly ? '$33.90' : '$14.59';
    document.getElementById('billingNote').innerHTML = isMonthly
      ? 'Billed monthly at <strong>$33.90/month</strong>.'
      : 'Billed as <strong>$174.50/year</strong>. After one year, renewal at $349.';
    document.getElementById('planName').textContent = isMonthly ? 'MONTHLY PLAN' : 'YEARLY PLAN';
    document.getElementById('creditsFeature').innerHTML = isMonthly
      ? '<strong>1 Plus credit</strong> per month'
      : '<strong>12 Plus credits</strong> every year';
    document.getElementById('pricingBadge').textContent = isMonthly ? 'Monthly plan' : 'Most popular — SAVE 57%';
    document.getElementById('saveBadge').style.display = isMonthly ? 'none' : '';
    card.classList.toggle('yearly', !isMonthly);
    document.getElementById('yearlyLabel').classList.toggle('active', !isMonthly);
    document.getElementById('monthlyLabel').classList.toggle('active', isMonthly);
  }

  // ===== FAQ ACCORDION =====
  function toggleFaq(btn) {
    const answer = btn.nextElementSibling;
    const isOpen = answer.classList.contains('open');
    // Close all
    document.querySelectorAll('.faq-answer').forEach(a => a.classList.remove('open'));
    document.querySelectorAll('.faq-question').forEach(q => q.classList.remove('open'));
    if (!isOpen) {
      answer.classList.add('open');
      btn.classList.add('open');
    }
  }

  // ===== CATALOG CAROUSEL =====
  let catalogOffset = 0;
  function shiftCatalog(dir) {
    const track = document.getElementById('catalogTrack');
    const cards = track.querySelectorAll('.course-card');
    const cardW = 220 + 16;
    const maxOffset = Math.max(0, cards.length - 4);
    catalogOffset = Math.max(0, Math.min(catalogOffset + dir, maxOffset));
    track.style.transform = `translateX(-${catalogOffset * cardW}px)`;
    document.getElementById('catalogPrev').disabled = catalogOffset === 0;
    document.getElementById('catalogNext').disabled = catalogOffset >= maxOffset;
  }

  // ===== CREDITS CAROUSEL =====
  let creditsOffset = 0;
  function shiftCredits(dir) {
    const track = document.getElementById('creditsTrack');
    const cards = track.querySelectorAll('.credit-card');
    const cardW = track.parentElement.offsetWidth / 3 + 24;
    const maxOffset = Math.max(0, cards.length - 3);
    creditsOffset = Math.max(0, Math.min(creditsOffset + dir, maxOffset));
    track.style.transform = `translateX(-${creditsOffset * cardW}px)`;
    document.getElementById('creditsPrev').disabled = creditsOffset === 0;
    document.getElementById('creditsNext').disabled = creditsOffset >= maxOffset;
  }
</script>

