<script>
  let passwordVisible = false;

  function togglePassword() {
    const input = document.getElementById('passwordInput');
    const eyeIcon = document.getElementById('eyeIcon');
    const eyeOffIcon = document.getElementById('eyeOffIcon');
    passwordVisible = !passwordVisible;
    input.type = passwordVisible ? 'text' : 'password';
    eyeIcon.style.display = passwordVisible ? 'none' : 'block';
    eyeOffIcon.style.display = passwordVisible ? 'block' : 'none';
  }

  function handleLogin(e) {
    e.preventDefault();
    const email = document.getElementById('emailInput').value;
    const password = document.getElementById('passwordInput').value;
    const errorEl = document.getElementById('formError');

    // Basic validation
    const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    const passwordValid = password.length >= 6;

    if (!emailValid || !passwordValid) {
      errorEl.style.display = 'block';
      if (!emailValid) document.getElementById('emailInput').classList.add('error');
      if (!passwordValid) document.getElementById('passwordInput').classList.add('error');
      return;
    }

    // Clear errors
    errorEl.style.display = 'none';
    document.getElementById('emailInput').classList.remove('error');
    document.getElementById('passwordInput').classList.remove('error');

    // Simulate login
    const btn = document.getElementById('submitBtn');
    btn.disabled = true;
    btn.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="animation:spin 1s linear infinite;"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg> Logging in…';

    setTimeout(() => {
      window.location.href = 'index.html';
    }, 1200);
  }

  function handleSocialLogin(provider) {
    const buttons = document.querySelectorAll('.social-btn');
    buttons.forEach(b => { b.disabled = true; b.style.opacity = '0.6'; });
    // Simulate redirect
    setTimeout(() => {
      window.location.href = 'index.html';
    }, 800);
  }

  // Clear error on input
  document.getElementById('emailInput').addEventListener('input', function() {
    this.classList.remove('error');
    document.getElementById('formError').style.display = 'none';
  });

  document.getElementById('passwordInput').addEventListener('input', function() {
    this.classList.remove('error');
    document.getElementById('formError').style.display = 'none';
  });
</script>

<style>
  @keyframes spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
  }
</style>

</body>
